{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.ras_easyecom_returns_intermediate as select * from ( select order_id ,INVOICE_ID ,replace(JSON_EXTRACT_SCALAR(RI,\'$.suborder_id\'),\'\"\',\'\') SUBORDER_ID ,REFERENCE_CODE ,CREDIT_NOTE_ID ,credit_note_number ,cast(ORDER_DATE as timestamp) ORDER_DATE ,cast(INVOICE_DATE as timestamp) INVOICE_DATE ,cast(RETURN_DATE as timestamp) RETURN_DATE ,cast(MANIFEST_DATE as timestamp) MANIFEST_DATE ,cast(IMPORT_DATE as timestamp) IMPORT_DATE ,cast(LAST_UPDATE_DATE as timestamp) LAST_UPDATE_DATE ,replace(JSON_EXTRACT_SCALAR(RI,\'$.company_product_id\'),\'\"\',\'\') COMPANY_PRODUCT_ID ,replace(JSON_EXTRACT_SCALAR(RI,\'$.productName\'),\'\"\',\'\') PRODUCTNAME ,replace(JSON_EXTRACT_SCALAR(RI,\'$.product_Id\'),\'\"\',\'\') PRODUCT_ID ,replace(JSON_EXTRACT_SCALAR(RI,\'$.sku\'),\'\"\',\'\') SKU ,MARKETPLACE ,MARKETPLACE_ID ,REPLACEMENT_ORDER ,replace(JSON_EXTRACT_SCALAR(RI,\'$.return_reason\'),\'\"\',\'\') RETURN_REASON ,replace(JSON_EXTRACT_SCALAR(RI,\'$.inventory_status\'),\'\"\',\'\') INVENTORY_STATUS ,cast(replace(JSON_EXTRACT_SCALAR(RI,\'$.returned_item_quantity\'),\'\"\',\'\') as float64) RETURNED_QUANTITY ,cast(replace(JSON_EXTRACT_SCALAR(RI,\'$.credit_note_total_item_excluding_tax\'),\'\"\',\'\') as float64) RETURN_AMOUNT_WITHOUT_TAX ,cast(replace(JSON_EXTRACT_SCALAR(RI,\'$.credit_note_total_item_tax\'),\'\"\',\'\') as float64) RETURN_TAX ,cast(replace(JSON_EXTRACT_SCALAR(RI,\'$.credit_note_total_item_shipping_charge\'),\'\"\',\'\') as float64) RETURN_SHIPPING_CHARGE ,cast(replace(JSON_EXTRACT_SCALAR(RI,\'$.credit_note_total_item_miscellaneous\'),\'\"\',\'\') as float64) RETURN_MISC ,ifnull(cast(replace(JSON_EXTRACT_SCALAR(RI,\'$.credit_note_total_item_excluding_tax\'),\'\"\',\'\') as float64),0) + ifnull(cast(replace(JSON_EXTRACT_SCALAR(RI,\'$.credit_note_total_item_tax\'),\'\"\',\'\') as float64),0) + ifnull(cast(replace(JSON_EXTRACT_SCALAR(RI,\'$.credit_note_total_item_shipping_charge\'),\'\"\',\'\') as float64),0) + ifnull(cast(replace(JSON_EXTRACT_SCALAR(RI,\'$.credit_note_total_item_miscellaneous\'),\'\"\',\'\') as float64),0) as TOTAL_RETURN_AMOUNT ,row_number() over (partition by order_id, Invoice_ID, REFERENCE_CODE, replace(JSON_EXTRACT_SCALAR(RI,\'$.suborder_id\'),\'\"\',\'\'),credit_note_id, credit_note_number order by cast(LAST_UPDATE_DATE as timestamp) desc) rw from maplemonk.EasyEcom_returns R left join UNNEST(ITEMS) RI ) where rw = 1; create or replace table ras-wh.maplemonk.ras_easyecom_returns_sales_data as with returns as ( select r.order_id , r.suborder_id , r.reference_code , r.order_date , r.return_date , r.last_update_date , r.company_product_id , r.productname as product_name , r.product_id , r.sku , r.marketplace , r.marketplace_id , r.replacement_order , r.return_reason , CASE WHEN r.return_reason IN (\"Returned\",\"Complaint - courier delay\",\"Seal Open\",\"Box Damage\",\"Product Damage\",\"Complaint - Damaged\",\"Part or Accessories missing\",\"Missing items\",\"Cancelled_after_invoice\",\"Empty box\",\"Complaint - Quality Issue\") THEN \"Customer Return\" ELSE \"Courier Return\" END AS return_type , CASE WHEN r.inventory_status IN (\"QC Pass\",\"Sold\") THEN \"Good Inventory\" ELSE \"Bad Inventory\" END AS inventory_type , r.total_return_amount from maplemonk.ras_easyecom_returns_intermediate r ) , sales as ( select s.order_quantity , s.ORDER_ID as order_id , s.CHANNEL , s.name as customer_name , s.EMAIL as customer_email , s.SHIPPING_LAST_UPDATE_DATE , s.SHIPPING_STATUS , s.SALEORDERITEMCODE , s.DELIVERED_DATE , s.RETURN_FLAG , s.returned_quantity , s.DAYS_IN_SHIPMENT , s.City , s.State , s.pincode , s.SELLING_PRICE , s.discount , s.order_date , s.PRODUCT_NAME , s.PRODUCT_ID , case when s.Payment_Mode in (\"COD\",\"CASH\") THEN TRUE ELSE FALSE end AS COD_Order , s.sales_order_item_id as suborder_id , s.courier as Shipping_Courier , s.SKU , s.new_customer_flag , s.order_status , LAST_DAY(DATE(s.Order_Date),MONTH) as month from maplemonk.ras_sales_consolidated s ), inventory as ( select case when i.brand IN (\"RBPL- MOODY\",\"MOODY\") THEN \"MOODY\" ELSE \"RAS\" END as brand , i.sku , i.product_name from `MAPLEMONK.ras_inventory_fact_items` i ), sku_master as ( select sm.sku , sm.brand from `MAPLEMONK.ras_sku_master` sm ), zone_mapping as ( select distinct Delivery_Pincode as pincode , Delivery_City as city , Delivery_state as state from maplemonk.RAS_DB_Pincode_Zone_Mapping ) select s.month , s.product_name , s.sku , s.order_id , s.suborder_id , s.product_id , coalesce (i.brand, case when sm.brand in (\"Moody Store\",\"Moody\",\"Moody Website\",\"B26779\") then \"MOODY\" else (case when sm.brand in (\"RAS LUXURY OILS\",\"RAS Luxury Oils India\",\"RAS Luxury Skincare\",\"RAS Luxury Oils\",\"RBPL - RAS\",\"RAS\",\"24KGOLDYOUDUO\",\"B12759\") then \"RAS\" else (case when sm.brand in(\"RBPL - RAS\") then \"RAS\" else \"MOODY\" end) end) end) as brand , CAST(s.order_date AS TIMESTAMP) as order_date , s.order_status , s.return_flag , r.return_type , r.inventory_type , r.return_date , r.last_update_date , r.return_reason , r.total_return_amount , r.replacement_order , s.returned_quantity , s.cod_order , s.selling_price , coalesce(z.city,s.city) as city , coalesce(z.state,s.state) as state , s.pincode , CASE WHEN s.pincode LIKE \'1%\' OR s.pincode LIKE \'2%\' THEN \'North Zone\' WHEN s.pincode LIKE \'3%\' OR s.pincode LIKE \'4%\' THEN \'West Zone\' WHEN s.pincode LIKE \'5%\' OR s.pincode LIKE \'6%\' THEN \'South Zone\' WHEN s.pincode LIKE \'7%\' OR s.pincode LIKE \'8%\' THEN \'East Zone\' ELSE NULL END AS zone , s.shipping_courier , s.customer_name , s.customer_email , s.new_customer_flag , s.channel from sales s left join returns r on r.order_id = s.order_id and r.suborder_id = s.suborder_id left join zone_mapping z on s.pincode = z.pincode left join inventory i on i.sku = s.sku and i.product_name = s.product_name left join sku_master sm on sm.sku = s.sku; create or replace table maplemonk.ras_returns_count_data as WITH orders as ( SELECT LAST_DAY(date(order_date), MONTH) as order_month, sum(return_flag) as returns_for_orders_of_month, count(*) as orders_for_the_month FROM maplemonk.ras_sales_consolidated GROUP BY order_month ), returns as ( SELECT LAST_DAY(DATE(return_date), MONTH) as return_month, COUNT(*) as total_returns_received_in_month FROM `MAPLEMONK.ras_easyecom_returns_intermediate` GROUP BY return_month ) SELECT o.order_month, o.returns_for_orders_of_month, o.orders_for_the_month, r.total_returns_received_in_month from orders o LEFT JOIN returns r ON r.return_month = o.order_month order by order_month desc;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

